CREATE TABLE IF NOT EXISTS brands(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,website_url TEXT);
CREATE TABLE IF NOT EXISTS catalog_perfumes(id TEXT PRIMARY KEY,brand_id INTEGER NOT NULL,name TEXT NOT NULL,year INTEGER,concentration TEXT,image_url TEXT,image_status TEXT NOT NULL DEFAULT 'pending',source_name TEXT NOT NULL,source_url TEXT NOT NULL,source_checked_at INTEGER,data_status TEXT NOT NULL DEFAULT 'verified',FOREIGN KEY(brand_id) REFERENCES brands(id));
CREATE TABLE IF NOT EXISTS catalog_notes(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,image_url TEXT,image_status TEXT NOT NULL DEFAULT 'pending',image_source_url TEXT);
CREATE TABLE IF NOT EXISTS perfume_note_groups(id INTEGER PRIMARY KEY AUTOINCREMENT,perfume_id TEXT NOT NULL,group_key TEXT NOT NULL,group_label TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,UNIQUE(perfume_id,group_key));
CREATE TABLE IF NOT EXISTS perfume_note_items(group_id INTEGER NOT NULL,note_id INTEGER NOT NULL,position INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(group_id,note_id));
CREATE TABLE IF NOT EXISTS perfume_profiles(perfume_id TEXT NOT NULL,profile_name TEXT NOT NULL,strength INTEGER NOT NULL CHECK(strength BETWEEN 0 AND 100),position INTEGER NOT NULL DEFAULT 0,source_kind TEXT NOT NULL DEFAULT 'editorial',PRIMARY KEY(perfume_id,profile_name));
CREATE TABLE IF NOT EXISTS catalog_import_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,provider TEXT NOT NULL,status TEXT NOT NULL,started_at INTEGER NOT NULL DEFAULT(unixepoch()),finished_at INTEGER,imported_count INTEGER NOT NULL DEFAULT 0,error_count INTEGER NOT NULL DEFAULT 0,notes TEXT);
